function miniSpark(values,color='#16845b'){const max=Math.max(...values),min=Math.min(...values),w=110,h=32,pts=values.map((v,i)=>`${i*w/(values.length-1)},${h-(v-min)/Math.max(1,max-min)*(h-4)-2}`).join(' ');return`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2" vector-effect="non-scaling-stroke"/><circle cx="${w}" cy="${pts.split(' ').at(-1).split(',')[1]}" r="2.5" fill="${color}"/></svg>`}
