function orderChannel(o){return o.channel||'Online mağaza'}
function orderMatchesTab(o){if(orderTab==='all')return true;if(orderTab==='unfulfilled')return!['Gönderildi','Teslim edildi','İptal'].includes(o.status);if(orderTab==='unpaid')return!['Ödendi','Manuel onay'].includes(o.payment);if(orderTab==='open')return!['Teslim edildi','İptal'].includes(o.status);if(orderTab==='closed')return['Teslim edildi','İptal'].includes(o.status);if(orderTab==='local')return o.city==='İstanbul';return true}
