function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let index=0;index<text.length;index++){const char=text[index],next=text[index+1];if(char==='"'&&quoted&&next==='"'){cell+='"';index++;continue}if(char==='"'){quoted=!quoted;continue}if(char===','&&!quoted){row.push(cell);cell='';continue}if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')index++;row.push(cell);if(row.some(value=>value.trim()))rows.push(row);row=[];cell='';continue}cell+=char}row.push(cell);if(row.some(value=>value.trim()))rows.push(row);if(rows.length<2)return[];const headers=rows.shift().map(header=>header.trim().toLocaleLowerCase('tr'));return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,values[index]??''])))}
async function importProductFile(file){const text=await file.text(),rows=file.name.toLocaleLowerCase('tr').endsWith('.json')?JSON.parse(text):parseCsv(text);if(!Array.isArray(rows)||!rows.length)throw new Error('Dosyada ürün kaydı bulunamadı');let imported=0,skipped=0;for(const [index,row]of rows.entries()){const rawId=Number(row.id)||0,existing=rawId?adminProducts.find(product=>product.id===rawId):null,name=String(row.name||row.ad||'').trim(),category=String(row.category||row.kategori||categoryList[0]).trim(),price=Number(row.price||row.fiyat)||0;if(!name||!price){skipped++;continue}const product=existing?structuredClone(existing):structuredClone(row);product.id=existing?.id||rawId||Date.now()+index;product.name=name;product.category=category;product.price=price;product.active=String(row.active??row.durum??'Aktif').toLocaleLowerCase('tr')!=='taslak';product.image=product.image||row.gorsel||row.görsel||'';if(!Array.isArray(product.variants)||!product.variants.length){if(existing?.variants?.length)product.variants=structuredClone(existing.variants);else if(product.image)product.variants=[{name:'Standart',hex:'#d8d2c8',image:product.image,sku:`VNT-${product.id}-1`,stock:Number(row.stock||row.stok)||0}];else{skipped++;continue}}if(row.stock||row.stok)product.variants[0].stock=Number(row.stock||row.stok)||0;product.media=Array.isArray(product.media)&&product.media.length?product.media:[product.image].filter(Boolean);await persistProduct(product);if(existing)Object.assign(existing,product);else adminProducts.unshift(product);imported++}if(!imported)throw new Error('Geçerli ürün bulunamadı; yeni ürünlerde ad, fiyat ve görsel zorunludur');renderProducts();renderInventory();renderMetrics();logActivity(`${imported} ürün içe aktarıldı`,'Ürünler');toast(`${imported} ürün içe aktarıldı${skipped?`, ${skipped} kayıt atlandı`:''}`)}
